def parse_expected(text):
    arr=[]
    for m in re.finditer(r'Demo pair \d+ output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance)',text,re.S):
        arr.append([[int(x) for x in row.split()] for row in m.group(1).strip().splitlines()])
    return arr
expects=[]
for t in texts: expects.extend(parse_expected(t))
